(function(){"use strict";const lecture={"id":"ec214-l22","label":"Lecture 2.2 • Unemployment & Inflation","description":"Labor-market classification, unemployment types, CPI/inflation and CPI biases.","cumulativeId":"ec214-l22-full-v1","cumulativeLabel":"Full Lecture • Lecture 2.2","parts":[{"id":"ec214-l22-labor-v1","label":"Part 1 • Employment & Labor-Market Indicators","description":"Classification rules, discouraged workers, hours and core labor formulas.","cards":[{"id":"macro-link","front":"How do GDP, employment, and unemployment usually move in the opening lecture note?","back":"GDP and employment tend to move together; unemployment tends to move opposite."},{"id":"employed-paid","front":"When is paid work enough to classify someone as employed?","back":"At least 1 hour of paid work in the lecture’s classification rule."},{"id":"employed-unpaid","front":"When can unpaid work count as employed?","back":"At least 15 hours of unpaid work under the lecture rule."},{"id":"temp-layoff","front":"Can someone not working this week still count as employed?","back":"Yes, if they still have a job and are temporarily laid off under the lecture classification."},{"id":"unemployed","front":"What conditions define an unemployed person?","back":"No employment + available for work + recent active job search or waiting for recall."},{"id":"four-weeks","front":"What job-search window does the lecture use for unemployment classification?","back":"Actively applied within the last four weeks, unless waiting to be recalled."},{"id":"discouraged","front":"How is a discouraged worker classified?","back":"Not unemployed and not in the labor force if no job-search effort was made in the last four weeks."},{"id":"full-time","front":"What weekly-hour threshold defines full-time in the lecture note?","back":"35 or more hours per week."},{"id":"part-time","front":"What is involuntary part-time work?","back":"Working part-time for economic reasons while wanting full-time work."},{"id":"aggregate-hours","front":"What are aggregate hours?","back":"Total hours worked by all workers during the period."},{"id":"unemp-problem-income","front":"Why is unemployment a macroeconomic problem?","back":"It causes lost income and lost production."},{"id":"unemp-human-cap","front":"How can unemployment damage human capital?","back":"Skills and productive capacity can deteriorate during prolonged unemployment."},{"id":"emp-pop","front":"State the employment-to-population ratio formula.","back":"Employed ÷ Working-age Population × 100."},{"id":"unemp-rate","front":"State the unemployment-rate formula.","back":"Unemployed ÷ Labor Force × 100."},{"id":"lfpr","front":"State the labor-force participation-rate formula.","back":"Labor Force ÷ Working-age Population × 100."},{"id":"denominator-trap","front":"What is the denominator of the unemployment rate?","back":"Labor force, not total population or working-age population."}]},{"id":"ec214-l22-unemployment-v1","label":"Part 2 • Sources & Types of Unemployment","description":"How unemployment begins/ends and frictional, structural, seasonal and cyclical unemployment.","cards":[{"id":"sources","front":"What are the four sources of unemployment listed in the lecture?","back":"Job losers, job leavers, entrants, and reentrants."},{"id":"ends","front":"How can an unemployment spell end?","back":"Hire, recall, or withdrawal from the labor force."},{"id":"frictional","front":"What is frictional unemployment?","back":"Normal labor turnover from people entering/leaving jobs and ongoing job creation/destruction."},{"id":"structural","front":"What is structural unemployment?","back":"A skills/location mismatch caused by changes such as technology or international competition."},{"id":"structural-example","front":"What lecture shift illustrates structural unemployment?","back":"Movement from labor-intensive toward capital/technology-intensive industries."},{"id":"seasonal","front":"What is seasonal unemployment?","back":"Employment changes tied to seasonal patterns, such as construction or farming."},{"id":"cyclical","front":"What is cyclical unemployment?","back":"Business-cycle unemployment: higher in recessions and lower in expansions."},{"id":"policy-type","front":"Why does the professor stress classifying unemployment correctly?","back":"Government support should match the underlying reason for unemployment."}]},{"id":"ec214-l22-cpi-v1","label":"Part 3 • CPI, Inflation, Headline & Core","description":"Fixed basket construction, CPI formula, inflation calculation and headline/core distinction.","cards":[{"id":"inflation","front":"What is inflation?","back":"A rise in the economy’s overall price level."},{"id":"inflation-rate","front":"What is the inflation rate?","back":"The percentage change in the price level from the previous period."},{"id":"cpi-def","front":"Define CPI.","back":"A weighted average of prices paid by urban consumers for a fixed market basket of consumption goods/services."},{"id":"cpi-use","front":"What is CPI mainly used to monitor?","back":"Changes in the cost of living over time."},{"id":"cpi-formula","front":"State the CPI formula.","back":"Cost of base-year basket at current prices ÷ cost of same basket at base-period prices × 100."},{"id":"infl-formula","front":"State the CPI inflation formula.","back":"(CPIₜ − CPIₜ₋₁) ÷ CPIₜ₋₁ × 100."},{"id":"fixed-qty","front":"What stays fixed when constructing the CPI basket?","back":"Base-year quantities."},{"id":"same-products","front":"Why survey the same or identical product types over time?","back":"To compare price changes rather than changes in what product is being measured."},{"id":"headline","front":"What is headline inflation?","back":"Inflation for the broad consumption basket, including food and energy."},{"id":"core","front":"What is core inflation?","back":"Inflation excluding raw food and energy."},{"id":"why-core","front":"Why is core inflation useful for policy monitoring?","back":"Food/energy prices are highly volatile and difficult to control, so core can show underlying pressure."}]},{"id":"ec214-l22-bias-deflator-v1","label":"Part 4 • CPI Biases & GDP Deflator","description":"Why CPI is imperfect and how its coverage differs from the GDP deflator.","cards":[{"id":"col","front":"What is cost of living?","back":"The money needed to achieve a certain standard of living."},{"id":"cpi-not-exact","front":"Why is CPI not an exact cost-of-living measure?","back":"It uses a fixed basket/identical-product assumptions and cannot capture every component of living standards."},{"id":"new-goods","front":"What is new-goods bias?","back":"New products may add value/quality before they enter the fixed CPI basket."},{"id":"quality","front":"What is quality-change bias?","back":"CPI can treat a price rise caused by better quality as too much pure inflation."},{"id":"commodity-sub","front":"What is commodity-substitution bias?","back":"Consumers switch toward relatively cheaper goods, but a fixed basket does not fully capture that response."},{"id":"outlet-sub","front":"What is outlet-substitution bias?","back":"Consumers may switch to discount outlets that the price survey does not fully capture."},{"id":"bias-direction","front":"What overall direction of CPI bias does the lecture note?","back":"A tendency to overstate inflation."},{"id":"deflator-formula","front":"State the GDP deflator formula.","back":"Nominal GDP ÷ Real GDP × 100."},{"id":"deflator-coverage","front":"What prices does the GDP deflator cover?","back":"All goods and services included in domestic GDP."},{"id":"cpi-coverage","front":"What prices does CPI cover?","back":"Consumer goods and services in the fixed market basket."},{"id":"weights","front":"How do CPI and GDP-deflator quantity weights differ?","back":"CPI uses past/base-basket quantities; the deflator reflects the changing domestic production mix."},{"id":"why-cpi-used","front":"Why is CPI still widely used despite biases?","back":"It is direct and understandable for consumer cost-of-living monitoring."}]}]};const root=window.D_STUDY_FLASHCARD_BANKS=window.D_STUDY_FLASHCARD_BANKS||{};const b=root.ec214||(root.ec214={title:"EC214 Complete Lecture Flashcards",bankVersion:"ec214-v13.14",lectures:[]});b.lectures=Array.isArray(b.lectures)?b.lectures:[];b.lectures=b.lectures.filter(function(x){return x&&x.id!==lecture.id});b.lectures.push(lecture);})();